export default async function install(app) {
  const palette = {
    bakerloo: '#B36305', central: '#E32017', circle: '#FFD300', district: '#00782A',
    'hammersmith-city': '#F3A9BB', jubilee: '#A0A5A9', metropolitan: '#9B0056',
    northern: '#000000', piccadilly: '#003688', victoria: '#0098D4', 'waterloo-city': '#95CDBA'
  };
  const fields = [
    { name: 'vehicle_id', type: 'string', alias: 'Vehicle' }, { name: 'line_id', type: 'string', alias: 'Line ID' },
    { name: 'line_name', type: 'string', alias: 'Line' }, { name: 'station', type: 'string', alias: 'Next station' },
    { name: 'platform', type: 'string', alias: 'Platform' }, { name: 'destination', type: 'string', alias: 'Destination' },
    { name: 'seconds_to_station', type: 'double', alias: 'Seconds to station' }, { name: 'status', type: 'string', alias: 'Status' },
    { name: 'observed_at', type: 'string', alias: 'TfL observation time' }
  ];
  const uniqueValueInfos = Object.entries(palette).map(([value, color]) => ({ value, symbol: { type: 'simple-marker', style: 'circle', color, size: 8, outline: { color: '#ffffff', width: 1 } } }));
  const popupHtml = `<div style="font-family:Arial,'Helvetica Neue',sans-serif;color:#1d1d1b;margin:-8px -10px -10px;min-width:250px;background:#fff;"><div style="height:66px;background:#0019a8;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden;"><div style="width:47px;height:47px;border-radius:50%;background:#e32017;border:6px solid #fff;box-sizing:border-box;position:absolute;left:22px;"></div><div style="background:#0019a8;color:#fff;font-weight:800;font-size:11px;letter-spacing:.6px;padding:4px 7px;z-index:1;">UNDERGROUND</div><div style="position:absolute;right:16px;color:#fff;font-size:10px;font-weight:bold;letter-spacing:1.1px;">LIVE</div></div><div style="padding:15px 16px 16px;border-top:5px solid #e32017;"><div style="color:#0019a8;font-size:20px;line-height:1.15;font-weight:800;margin-bottom:4px;">{line_name} line</div><div style="color:#4b4b4b;font-size:13px;margin-bottom:14px;">Train <strong>{vehicle_id}</strong> · {status}</div><div style="display:flex;border-top:1px solid #d9d9d9;padding:10px 0 8px;gap:12px;"><div style="width:40%;font-size:11px;text-transform:uppercase;letter-spacing:.7px;color:#6b6b6b;font-weight:bold;">Next stop</div><div style="width:60%;font-size:14px;color:#1d1d1b;font-weight:bold;">{station}</div></div><div style="display:flex;border-top:1px solid #d9d9d9;padding:8px 0;gap:12px;"><div style="width:40%;font-size:11px;text-transform:uppercase;letter-spacing:.7px;color:#6b6b6b;font-weight:bold;">Towards</div><div style="width:60%;font-size:14px;color:#1d1d1b;">{destination}</div></div><div style="display:flex;border-top:1px solid #d9d9d9;padding:8px 0;gap:12px;"><div style="width:40%;font-size:11px;text-transform:uppercase;letter-spacing:.7px;color:#6b6b6b;font-weight:bold;">Platform</div><div style="width:60%;font-size:14px;color:#1d1d1b;">{platform}</div></div><div style="display:flex;align-items:center;justify-content:space-between;background:#f4f4f4;margin-top:10px;padding:10px 12px;border-left:4px solid #0019a8;"><span style="font-size:11px;text-transform:uppercase;letter-spacing:.7px;color:#555;font-weight:bold;">Due in</span><span style="font-size:20px;color:#0019a8;font-weight:800;">{seconds_to_station} sec</span></div><div style="font-size:10px;color:#6b6b6b;margin-top:12px;">TfL live prediction · {observed_at}</div></div></div>`;
  const result = await app.createResultLayer({ id: 'tfl-live-trains', title: 'TfL live trains — refreshed every 5 seconds', geometryType: 'point', fields, renderer: { type: 'unique-value', field: 'line_id', uniqueValueInfos, defaultSymbol: { type: 'simple-marker', color: '#777777', size: 8, outline: { color: '#ffffff', width: 1 } } }, popupTemplate: { title: 'TfL Underground live train', content: [{ type: 'text', text: popupHtml }] } });
  result.layer.effect = 'drop-shadow(2px, 2px, 3px)';
  const response = await fetch(app.config.stationsUrl); app.assert(response.ok, `TfL station directory request failed (${response.status}).`);
  const directory = await response.json(); const stations = new Map(); for (const stop of directory.stopPoints ?? []) if (stop.stopType === 'NaptanMetroStation' && Number.isFinite(stop.lat) && Number.isFinite(stop.lon)) stations.set(stop.id, [stop.lon, stop.lat]); app.assert(stations.size > 0, 'TfL station directory did not return station coordinates.');
  let busy = false; let latest = 0;
  const refresh = async () => { if (busy) return; busy = true; try { const request = ++latest; const response = await fetch(app.config.arrivalsUrl); if (!response.ok) throw new Error(`TfL arrivals request failed (${response.status}).`); const arrivals = await response.json(); const byVehicle = new Map(); for (const prediction of arrivals) { const previous = byVehicle.get(prediction.vehicleId); if (!previous || Number(prediction.timeToStation) < Number(previous.timeToStation)) byVehicle.set(prediction.vehicleId, prediction); } const features = []; for (const prediction of byVehicle.values()) { const coordinate = stations.get(prediction.naptanId); if (!coordinate) continue; features.push({ geometry: { type: 'point', longitude: coordinate[0], latitude: coordinate[1] }, attributes: { vehicle_id: String(prediction.vehicleId ?? ''), line_id: String(prediction.lineId ?? ''), line_name: String(prediction.lineName ?? ''), station: String(prediction.stationName ?? ''), platform: String(prediction.platformName ?? ''), destination: String(prediction.destinationName ?? ''), seconds_to_station: Number(prediction.timeToStation ?? 0), status: String(prediction.currentLocation ?? ''), observed_at: String(prediction.timestamp ?? '') } }); } if (request === latest) { await result.replaceFeatures(features); app.setStatus(`TfL train markers refreshed: ${features.length} trains at ${new Date().toLocaleTimeString()}.`); } } catch (error) { app.setStatus(`TfL update delayed: ${error.message}`); } finally { busy = false; } };
  await refresh(); const timer = setInterval(() => { void refresh(); }, app.config.refreshMs); app.onCleanup(() => clearInterval(timer));
}